fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    x1.iter()
      .zip(x2.iter())
      .map(|(&a, &b)| a & b)
      .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_bitwise_and_basic() {
        let a = vec![0b0000_0000, 0b1111_1111, 0b1010_1010];
        let b = vec![0b1111_1111, 0b0000_0000, 0b0101_0101];
        let result = bitwise_and(&a, &b);
        assert_eq!(result, vec![0b0000_0000, 0b0000_0000, 0b0000_0000]);

        let a = vec![1, 2, 3, 4];
        let b = vec![4, 3, 2, 1];
        let result = bitwise_and(&a, &b);
        // 1&4 = 0, 2&3 = 2, 3&2 = 2, 4&1 = 0
        assert_eq!(result, vec![0, 2, 2, 0]);
    }
}